import random
from fractions import Fraction

def gaussian_elimination(A, b):
    n = len(b)
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]
        b[i], b[max_row] = b[max_row], b[i]
        for j in range(i+1, n):
            factor = Fraction(A[j][i], A[i][i])
            for k in range(n):
                A[j][k] -= factor * A[i][k]
            b[j] -= factor * b[i]
    x = [0]*n
    for i in range(n-1, -1, -1):
        x[i] = Fraction(b[i], A[i][i])
        for j in range(i):
            b[j] -= A[j][i] * x[i]
    return x

def matrix_multiply(A, B):
    n = len(A)
    C = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def dpll_width(instance):
    n = len(instance)
    clauses = [set(clause) for clause in instance]
    variables = set()
    for clause in clauses:
        variables.update(clause)

    def is_satisfiable(model):
        for clause in clauses:
            if not any(var in model and model[var] == 1 for var in clause):
                return False
        return True

    def dpll(model, literals):
        if len(literals) == 0:
            return is_satisfiable(model)

        literal = literals[0]
        pos_literal = literal
        neg_literal = -literal

        model[pos_literal] = 1
        if dpll(model, literals[1:]):
            return True

        del model[pos_literal]
        model[neg_literal] = 0
        if dpll(model, literals[1:]):
            return True

        del model[neg_literal]
        return False

    max_width = 0
    for literal in variables:
        model = {}
        if dpll(model, [literal]):
            width = len(model)
            if width > max_width:
                max_width = width
    return max_width

